cd /home/thomasphillip/Projects/vox/.codex/production-runs/2026-09-05-after-the-hearth
mkdir -p logs/manual-recovery-candidate-runtime
D=logs/manual-recovery-candidate-runtime
{ date -u +"observedAtUtc=%Y-%m-%dT%H:%M:%SZ";
  echo "--- self fd table (bash tool)"; ls -l /proc/self/fd/;
  echo "--- agent process 2329126 fd 9"; ls -l /proc/2329126/fd/9;
  echo "--- heavy.lock stat"; stat -c 'path=%n ino=%i dev=%d size=%s' /home/thomasphillip/Projects/Paraform/harness/output/.heavy.lock;
  echo "--- systemwide fds referencing heavy.lock (count)"; ls -l /proc/*/fd/* 2>/dev/null | grep -c heavy.lock;
  echo "--- /proc/locks rows"; wc -l < /proc/locks;
  echo "--- /proc/locks rows matching inode 8397196"; awk '{split($5,a,":"); if (a[3]=="8397196") print}' /proc/locks | wc -l;
} > $D/heavy-lock-gate-evidence.txt 2>&1
sha256sum $D/heavy-lock-gate-evidence.txt; date -u +"%Y-%m-%dT%H:%M:%SZ"
